pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testRegression_property() public {
        c.init(address(0), address(0), address(0));
        c.newAddressProposal(address(0x1), "DAO");
        c.newGrantProposal(address(0x2), 100);
        uint256 propCount = c.proposalCount();
        assertTrue(propCount == 2, "proposalCount should be 2 after two proposals");
    }
}
